function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const EXTRACTION_HISTORY_TABLE = 6; // データ抽出履歴
  const REPORT_OUTPUT_TABLE = 7; // レポート出力履歴
  const SUPPLIER_TABLE = 1; // 仕入先マスタ
  const ORDER_HISTORY_TABLE = 3; // 発注履歴
  const INVENTORY_TABLE = 4; // 在庫データ
  const STOCKTAKING_TABLE = 5; // 棚卸データ

  // 履歴テーブル再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString('ja-JP') : ''}</td>
        <td>${r.仕入先名 || ''}</td>
        <td>${r.抽出種別 || ''}</td>
        <td>${r.抽出件数 || 0}件</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${r.処理ステータス === '完了' ? 'rgba(34, 197, 94, 0.1)' : 'rgba(239, 68, 68, 0.1)'}; color: ${r.処理ステータス === '完了' ? '#22c562' : '#ef4444'};">
            ${r.処理ステータス || ''}
          </span>
        </td>
        <td>
          <button class="action-btn secondary download-btn" data-id="${r.id}" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); padding: 4px 8px; border-radius: 3px; font-size: 12px;">
            DL
          </button>
        </td>
      </tr>
    `).join("");
  }

  // プレビューテーブル再描画関数
  function renderPreviewRows(data) {
    const tbody = container.querySelector("#preview-tbody");
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getTypeColor(item.type).bg}; color: ${getTypeColor(item.type).text};">
            ${item.type}
          </span>
        </td>
        <td>${item.productName}</td>
        <td>${item.quantity}</td>
        <td>${item.amount}</td>
        <td>${item.date}</td>
      </tr>
    `).join("");
  }

  function getTypeColor(type) {
    switch(type) {
      case '発注': return { bg: 'rgba(34, 197, 94, 0.1)', text: '#22c562' };
      case '在庫': return { bg: 'rgba(59, 130, 246, 0.1)', text: '#3b82f6' };
      case '棚卸': return { bg: 'rgba(168, 85, 247, 0.1)', text: '#a855f7' };
      default: return { bg: 'rgba(156, 163, 175, 0.1)', text: '#9ca3af' };
    }
  }

  // 仕入先選択肢を動的に設定
  async function loadSuppliers() {
    const suppliers = await window.aivicApi.list(SUPPLIER_TABLE);
    if (suppliers) {
      const select = container.querySelector("#supplier-select");
      const currentOptions = select.innerHTML;
      const supplierOptions = suppliers.map(s => 
        `<option value="${s.id}">${s.仕入先名}</option>`
      ).join("");
      select.innerHTML = currentOptions + supplierOptions;
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const historyData = await window.aivicApi.list(EXTRACTION_HISTORY_TABLE);
    if (historyData) {
      renderHistoryRows(historyData);
    }
    await loadSuppliers();
  }

  // データ抽出実行
  container.querySelector("#btn-extract").addEventListener("click", async () => {
    const supplierId = container.querySelector("#supplier-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#category-select").value;

    const dataTypes = [];
    if (container.querySelector("#data-orders").checked) dataTypes.push("orders");
    if (container.querySelector("#data-inventory").checked) dataTypes.push("inventory");
    if (container.querySelector("#data-stocktaking").checked) dataTypes.push("stocktaking");

    if (!supplierId) {
      alert("仕入先を選択してください");
      return;
    }
    if (dataTypes.length === 0) {
      alert("データ種別を選択してください");
      return;
    }

    // 抽出処理実行（履歴に記録）
    const extractionRecord = {
      抽出種別: dataTypes.join(","),
      仕入先ID: supplierId,
      抽出条件: JSON.stringify({ startDate, endDate, category }),
      処理ステータス: "実行中",
      処理開始日時: new Date().toISOString(),
      実行ユーザーID: "current-user"
    };

    const saved = await window.aivicApi.save(EXTRACTION_HISTORY_TABLE, extractionRecord);
    if (saved) {
      // プレビューデータを生成（実際の実装では各テーブルからデータを抽出）
      const previewData = [
        { type: "発注", productName: "構造用合板 12mm", quantity: "50枚", amount: "¥125,000", date: "2024-01-10" },
        { type: "在庫", productName: "角材 4×4", quantity: "120本", amount: "¥84,000", date: "2024-01-12" },
        { type: "棚卸", productName: "断熱材", quantity: "30巻", amount: "¥45,000", date: "2024-01-13" }
      ];

      renderPreviewRows(previewData);

      // 履歴を更新（完了ステータス）
      await window.aivicApi.update(EXTRACTION_HISTORY_TABLE, saved.id, {
        処理ステータス: "完了",
        処理完了日時: new Date().toISOString(),
        抽出件数: previewData.length
      });

      // 履歴テーブルを再読み込み
      const updatedHistory = await window.aivicApi.list(EXTRACTION_HISTORY_TABLE);
      if (updatedHistory) {
        renderHistoryRows(updatedHistory);
      }

      // 最終更新時刻を更新
      container.querySelector("#last-updated").textContent = new Date().toLocaleString('ja-JP');
    }
  });

  // レポート生成
  container.querySelector("#btn-generate-report").addEventListener("click", async () => {
    const format = container.querySelector('input[name="output-format"]:checked').value;
    const supplierId = container.querySelector("#supplier-select").value;

    if (!supplierId) {
      alert("仕入先を選択してください");
      return;
    }

    const reportRecord = {
      仕入先ID: supplierId,
      レポート種別: "データ抽出レポート",
      レポート名: `データ抽出_${new Date().toISOString().slice(0,10)}`,
      出力形式: format.toUpperCase(),
      対象期間開始日: container.querySelector("#start-date").value,
      対象期間終了日: container.querySelector("#end-date").value,
      出力件数: 3,
      ファイルサイズ: 1024,
      出力ステータス: "成功",
      ダウンロード回数: 0,
      作成者ID: "current-user"
    };

    const saved = await window.aivicApi.save(REPORT_OUTPUT_TABLE, reportRecord);
    if (saved) {
      alert(`${format.toUpperCase()}レポートを生成しました`);
      // 実際の実装では、ここでファイルダウンロードを実行
      window.showScreen('scr-1780996715569'); // レポート生成処理画面へ
    }
  });

  // 共有リンク作成
  container.querySelector("#btn-share-link").addEventListener("click", () => {
    const shareUrl = `${window.location.origin}/shared/report/${Date.now()}`;
    navigator.clipboard.writeText(shareUrl).then(() => {
      alert(`共有リンクをクリップボードにコピーしました:\n${shareUrl}`);
    });
  });

  // メール送信
  container.querySelector("#btn-send-email").addEventListener("click", () => {
    const email = container.querySelector("#email-input").value;
    if (!email) {
      alert("メールアドレスを入力してください");
      return;
    }
    alert(`${email} にレポートを送信しました`);
  });

  // 履歴からのダウンロード
  container.addEventListener("click", (e) => {
    const downloadBtn = e.target.closest(".download-btn");
    if (downloadBtn) {
      const historyId = downloadBtn.dataset.id;
      alert(`履歴ID: ${historyId} のレポートをダウンロードします`);
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const INVENTORY_TABLE = 4; // 棚卸データ
  const REPORT_HISTORY_TABLE = 7; // レポート出力履歴
  const SUPPLIER_TABLE = 1; // 仕入先マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ

  // DOM要素取得
  const generateBtn = container.querySelector('#generate-btn');
  const progressContainer = container.querySelector('#progress-container');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const previewArea = container.querySelector('#preview-area');
  const dataCount = container.querySelector('#data-count');
  const historyTbody = container.querySelector('#history-tbody');
  const refreshHistoryBtn = container.querySelector('#refresh-history-btn');

  // 履歴テーブル再描画
  function renderHistoryRows(rows) {
    historyTbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">
          ${row.作成日時 ? new Date(row.作成日時).toLocaleString('ja-JP') : ''}
        </td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">
          ${row.レポート名 || ''}
        </td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">
          <span style="padding: 2px 6px; background: ${row.出力形式 === 'Excel' ? '#22c55e' : '#3b82f6'}; color: white; border-radius: 3px; font-size: 11px;">
            ${row.出力形式 || ''}
          </span>
        </td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">
          ${row.出力件数 || 0}件
        </td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">
          <span style="padding: 2px 6px; background: ${row.出力ステータス === '成功' ? '#22c55e' : row.出力ステータス === '失敗' ? '#ef4444' : '#f59e0b'}; color: white; border-radius: 3px; font-size: 11px;">
            ${row.出力ステータス || ''}
          </span>
        </td>
        <td style="padding: 6px 8px; font-size: 12px;">
          ${row.出力ステータス === '成功' ? `<button class="action-btn secondary download-btn" data-id="${row.id}" style="padding: 2px 6px; font-size: 11px;">ダウンロード</button>` : ''}
        </td>
      </tr>
    `).join('');
  }

  // 仕入先選択肢を動的に設定
  function loadSuppliers() {
    window.aivicApi.list(SUPPLIER_TABLE).then(suppliers => {
      if (suppliers) {
        const supplierSelect = container.querySelector('#supplier-select');
        const currentOptions = supplierSelect.innerHTML;
        const dynamicOptions = suppliers.filter(s => s.有効フラグ).map(s => 
          `<option value="${s.id}">${s.仕入先名}</option>`
        ).join('');
        supplierSelect.innerHTML = currentOptions.split('</option>')[0] + '</option>' + dynamicOptions;
      }
    });
  }

  // 棚卸データ件数を更新
  function updateDataCount() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const supplierId = container.querySelector('#supplier-select').value;
    const status = container.querySelector('#status-filter').value;

    window.aivicApi.list(INVENTORY_TABLE).then(inventoryData => {
      if (inventoryData) {
        let filteredData = inventoryData;

        // 期間フィルタ
        if (startDate) {
          filteredData = filteredData.filter(item => 
            new Date(item.棚卸日) >= new Date(startDate)
          );
        }
        if (endDate) {
          filteredData = filteredData.filter(item => 
            new Date(item.棚卸日) <= new Date(endDate)
          );
        }

        // 仕入先フィルタ
        if (supplierId) {
          filteredData = filteredData.filter(item => item.仕入先ID === supplierId);
        }

        // ステータスフィルタ
        if (status) {
          const statusMap = {
            'completed': '完了',
            'pending': '実施中',
            'approved': '承認済み'
          };
          filteredData = filteredData.filter(item => item.棚卸ステータス === statusMap[status]);
        }

        dataCount.textContent = `対象データ: ${filteredData.length}件`;
      }
    });
  }

  // プレビュー生成
  function generatePreview(data) {
    if (!data || data.length === 0) {
      previewArea.innerHTML = '<div style="color: var(--text-muted); font-size: 13px;">データがありません</div>';
      return;
    }

    const previewHtml = `
      <div style="padding: 12px; height: 100%; overflow-y: auto;">
        <div style="font-size: 14px; font-weight: 600; color: var(--text); margin-bottom: 12px; text-align: center;">
          棚卸レポート プレビュー
        </div>
        <table style="width: 100%; font-size: 11px;">
          <thead>
            <tr style="background: rgba(255,255,255,0.1);">
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">棚卸日</th>
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">商品名</th>
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">帳簿在庫</th>
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">実在庫</th>
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">差異</th>
              <th style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">状況</th>
            </tr>
          </thead>
          <tbody>
            ${data.slice(0, 10).map(item => `
              <tr>
                <td style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">
                  ${item.棚卸日 ? new Date(item.棚卸日).toLocaleDateString('ja-JP') : ''}
                </td>
                <td style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">
                  商品${Math.floor(Math.random() * 100) + 1}
                </td>
                <td style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18); text-align: right;">
                  ${item.帳簿在庫数 || 0}
                </td>
                <td style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18); text-align: right;">
                  ${item.実在庫数 || 0}
                </td>
                <td style="padding: 4px 6px; border: 1px solid rgba(255,255,255,0.18); text-align: right; color: ${item.差異数 > 0 ? '#22c55e' : item.差異数 < 0 ? '#ef4444' : 'var(--text)'};">
                  ${item.差異数 || 0}
                </td>
                <td style="padding: 4px 6px; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">
                  ${item.棚卸ステータス || ''}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
        ${data.length > 10 ? `<div style="text-align: center; margin-top: 8px; color: var(--text-muted); font-size: 11px;">他 ${data.length - 10}件...</div>` : ''}
      </div>
    `;
    previewArea.innerHTML = previewHtml;
  }

  // レポート生成処理
  function generateReport() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const supplierId = container.querySelector('#supplier-select').value;
    const status = container.querySelector('#status-filter').value;
    const format = container.querySelector('input[name="format"]:checked').value;

    if (!startDate || !endDate) {
      alert('対象期間を設定してください');
      return;
    }

    // 進捗表示開始
    progressContainer.style.display = 'block';
    generateBtn.disabled = true;
    generateBtn.textContent = '生成中...';

    // 進捗アニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.floor(progress) + '%';
    }, 200);

    // データ取得とレポート生成
    window.aivicApi.list(INVENTORY_TABLE).then(inventoryData => {
      if (inventoryData) {
        // フィルタリング処理（updateDataCount と同じロジック）
        let filteredData = inventoryData;

        if (startDate) {
          filteredData = filteredData.filter(item => 
            new Date(item.棚卸日) >= new Date(startDate)
          );
        }
        if (endDate) {
          filteredData = filteredData.filter(item => 
            new Date(item.棚卸日) <= new Date(endDate)
          );
        }
        if (supplierId) {
          filteredData = filteredData.filter(item => item.仕入先ID === supplierId);
        }
        if (status) {
          const statusMap = {
            'completed': '完了',
            'pending': '実施中', 
            'approved': '承認済み'
          };
          filteredData = filteredData.filter(item => item.棚卸ステータス === statusMap[status]);
        }

        // プレビュー生成
        generatePreview(filteredData);

        // レポート履歴に保存
        const reportData = {
          仕入先ID: supplierId || null,
          レポート種別: '棚卸レポート',
          レポート名: `棚卸レポート_${startDate}_${endDate}`,
          出力形式: format === 'excel' ? 'Excel' : 'PDF',
          対象期間開始日: startDate,
          対象期間終了日: endDate,
          出力件数: filteredData.length,
          ファイルサイズ: Math.floor(Math.random() * 500000) + 100000,
          出力ステータス: '成功',
          ダウンロード回数: 0,
          作成者ID: 'current-user-id'
        };

        window.aivicApi.save(REPORT_HISTORY_TABLE, reportData).then(() => {
          // 進捗完了
          clearInterval(progressInterval);
          progressBar.style.width = '100%';
          progressText.textContent = '100%';

          setTimeout(() => {
            progressContainer.style.display = 'none';
            generateBtn.disabled = false;
            generateBtn.textContent = 'レポート生成';

            // 履歴更新
            loadReportHistory();
          }, 1000);
        });
      }
    });
  }

  // 履歴読み込み
  function loadReportHistory() {
    window.aivicApi.list(REPORT_HISTORY_TABLE).then(rows => {
      if (rows) {
        const sortedRows = rows.sort((a, b) => new Date(b.作成日時) - new Date(a.作成日時));
        renderHistoryRows(sortedRows);
      }
    });
  }

  // 初期データ読み込み
  renderHistoryRows(tables[REPORT_HISTORY_TABLE]?.records || []);
  loadSuppliers();
  updateDataCount();

  // イベントリスナー
  generateBtn.addEventListener('click', generateReport);
  refreshHistoryBtn.addEventListener('click', loadReportHistory);

  // 条件変更時のデータ件数更新
  ['#start-date', '#end-date', '#supplier-select', '#status-filter'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', updateDataCount);
  });

  // カテゴリチェックボックス変更時
  ['#category-steel', '#category-concrete', '#category-wood', '#category-electric'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', updateDataCount);
  });

  // ダウンロードボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const downloadBtn = e.target.closest('.download-btn');
    if (downloadBtn) {
      const reportId = downloadBtn.dataset.id;

      // ダウンロード処理（実際のファイルダウンロードをシミュレート）
      const link = document.createElement('a');
      link.href = '#'; // 実際の環境ではファイルURLを設定
      link.download = `棚卸レポート_${new Date().toISOString().split('T')[0]}.xlsx`;
      link.click();

      // ダウンロード回数を更新
      window.aivicApi.list(REPORT_HISTORY_TABLE).then(reports => {
        const report = reports.find(r => r.id === reportId);
        if (report) {
          window.aivicApi.update(REPORT_HISTORY_TABLE, reportId, {
            ダウンロード回数: (report.ダウンロード回数 || 0) + 1,
            最終ダウンロード日時: new Date().toISOString()
          }).then(() => {
            loadReportHistory();
          });
        }
      });
    }
  });
}

function(container, apiUrl, tables) {
  let currentReportData = null;

  // レポート履歴テーブルの再描画
  function renderReportHistory(reports) {
    const tbody = container.querySelector('#report-history-tbody');
    if (!reports || reports.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 14px;">履歴がありません</td></tr>';
      return;
    }

    tbody.innerHTML = reports.map(report => {
      const statusColor = report.出力ステータス === '成功' ? '#22c55e' : 
                         report.出力ステータス === '失敗' ? '#ef4444' : '#f59e0b';
      const periodText = report.対象期間開始日 && report.対象期間終了日 ? 
        `${new Date(report.対象期間開始日).toLocaleDateString()} - ${new Date(report.対象期間終了日).toLocaleDateString()}` : '-';

      return `
        <tr data-id="${report.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${new Date(report.作成日時).toLocaleString()}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${report.レポート種別 || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${periodText}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${report.出力形式 || '-'}</td>
          <td style="padding: 10px 12px; font-size: 13px;">
            <span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; background: ${statusColor}20; color: ${statusColor}; border: 1px solid ${statusColor}40;">
              ${report.出力ステータス || '処理中'}
            </span>
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            ${report.出力ステータス === '成功' ? 
              `<button class="action-btn secondary download-btn" data-id="${report.id}" style="padding: 4px 8px; font-size: 11px;">ダウンロード</button>
               <button class="action-btn secondary preview-btn" data-id="${report.id}" style="padding: 4px 8px; font-size: 11px; margin-left: 4px;">プレビュー</button>` :
              '<span style="color: var(--text-muted); font-size: 11px;">-</span>'
            }
          </td>
        </tr>
      `;
    }).join('');
  }

  // プレビュー表示
  function showPreview(reportData) {
    const previewArea = container.querySelector('#preview-area');

    if (!reportData) {
      previewArea.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 14px; padding: 40px 0;">プレビューデータがありません</div>';
      return;
    }

    // サンプルデータでプレビューテーブルを生成
    const sampleData = generateSampleReportData(reportData.レポート種別);

    previewArea.innerHTML = `
      <div style="margin-bottom: 12px;">
        <h4 style="margin: 0; font-size: 14px; color: var(--text); font-weight: 600;">${reportData.レポート名 || 'レポート'}</h4>
        <p style="margin: 4px 0 0 0; font-size: 12px; color: var(--text-muted);">生成日時: ${new Date(reportData.作成日時).toLocaleString()}</p>
      </div>
      <div style="max-height: 200px; overflow: auto;">
        <table style="width: 100%; font-size: 12px;">
          <thead>
            <tr style="background: rgba(255,255,255,0.05);">
              ${sampleData.headers.map(h => `<th style="padding: 6px 8px; text-align: left; color: var(--text); border-bottom: 1px solid var(--border);">${h}</th>`).join('')}
            </tr>
          </thead>
          <tbody>
            ${sampleData.rows.map(row => `
              <tr style="border-bottom: 1px solid rgba(255,255,255,0.03);">
                ${row.map(cell => `<td style="padding: 6px 8px; color: var(--text);">${cell}</td>`).join('')}
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // サンプルレポートデータ生成
  function generateSampleReportData(reportType) {
    switch(reportType) {
      case 'order-history':
        return {
          headers: ['発注日', '仕入先', '商品名', '数量', '単価', '金額'],
          rows: [
            ['2024/01/15', '株式会社山田建材', '構造用合板12mm', '50', '2,800', '140,000'],
            ['2024/01/16', '田中工業株式会社', 'コンクリート釘', '200', '150', '30,000'],
            ['2024/01/17', '佐藤商事', '断熱材グラスウール', '30', '1,200', '36,000']
          ]
        };
      case 'inventory-status':
        return {
          headers: ['商品名', '現在庫', '安全在庫', '状況', '最終入庫日'],
          rows: [
            ['構造用合板12mm', '25', '20', '正常', '2024/01/20'],
            ['コンクリート釘', '150', '100', '正常', '2024/01/18'],
            ['断熱材グラスウール', '5', '15', '不足', '2024/01/10']
          ]
        };
      default:
        return {
          headers: ['項目', '値'],
          rows: [
            ['総件数', '123'],
            ['処理日時', new Date().toLocaleString()]
          ]
        };
    }
  }

  // 進捗表示
  function showProgress() {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressContainer.style.display = 'block';

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setTimeout(() => {
          progressContainer.style.display = 'none';
          loadReportHistory();
        }, 500);
      }
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.round(progress) + '%';
    }, 200);
  }

  // レポート履歴読み込み
  async function loadReportHistory() {
    try {
      const reports = await window.aivicApi.list(6); // レポート出力履歴テーブル
      renderReportHistory(reports || []);
    } catch (error) {
      console.error('レポート履歴の読み込みに失敗:', error);
      renderReportHistory([]);
    }
  }

  // 初期データ読み込み
  renderReportHistory(tables[6]?.records || []);
  loadReportHistory();

  // レポート生成ボタン
  container.querySelector('#btn-generate').addEventListener('click', async () => {
    const reportType = container.querySelector('#report-type').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const outputFormat = container.querySelector('input[name="output-format"]:checked')?.value;

    if (!reportType) {
      alert('レポート種別を選択してください');
      return;
    }

    if (!outputFormat) {
      alert('出力形式を選択してください');
      return;
    }

    // 選択された仕入先を取得
    const selectedSuppliers = Array.from(container.querySelectorAll('#supplier-checkboxes input[type="checkbox"]:checked'))
      .map(cb => cb.value);

    showProgress();

    // レポート出力履歴に保存
    const reportData = {
      仕入先ID: selectedSuppliers[0] || 'supplier-001',
      レポート種別: reportType,
      レポート名: getReportName(reportType),
      出力形式: outputFormat.toUpperCase(),
      対象期間開始日: startDate || null,
      対象期間終了日: endDate || null,
      出力件数: Math.floor(Math.random() * 1000) + 10,
      ファイルサイズ: Math.floor(Math.random() * 500000) + 50000,
      出力ステータス: '成功',
      エラーメッセージ: null,
      ダウンロード回数: 0,
      最終ダウンロード日時: null,
      作成者ID: 'user-001'
    };

    try {
      const saved = await window.aivicApi.save(6, reportData);
      if (saved) {
        currentReportData = saved;
        showPreview(saved);
      }
    } catch (error) {
      console.error('レポート生成に失敗:', error);
    }
  });

  // レポート名取得
  function getReportName(reportType) {
    const names = {
      'order-history': '発注履歴レポート',
      'inventory-status': '在庫状況レポート',
      'stocktaking-result': '棚卸結果レポート',
      'supplier-summary': '仕入先別サマリー',
      'product-analysis': '商品分析レポート'
    };
    return names[reportType] || 'レポート';
  }

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#report-type').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#category').value = '';
    container.querySelectorAll('#supplier-checkboxes input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('input[name="output-format"][value="csv"]').checked = true;

    const previewArea = container.querySelector('#preview-area');
    previewArea.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 14px; padding: 40px 0;">レポートを生成するとプレビューが表示されます</div>';
  });

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    loadReportHistory();
  });

  // 行レベル操作（ダウンロード・プレビュー）
  container.addEventListener('click', async (e) => {
    const downloadBtn = e.target.closest('.download-btn');
    const previewBtn = e.target.closest('.preview-btn');

    if (downloadBtn) {
      const reportId = downloadBtn.dataset.id;
      // ダウンロード処理（実際の実装では blob を生成）
      alert('ダウンロードを開始します');

      // ダウンロード回数を更新
      try {
        await window.aivicApi.update(6, reportId, {
          ダウンロード回数: 1,
          最終ダウンロード日時: new Date().toISOString()
        });
        loadReportHistory();
      } catch (error) {
        console.error('ダウンロード履歴の更新に失敗:', error);
      }
    }

    if (previewBtn) {
      const reportId = previewBtn.dataset.id;
      try {
        const reports = await window.aivicApi.list(6);
        const report = reports.find(r => r.id === reportId);
        if (report) {
          showPreview(report);
        }
      } catch (error) {
        console.error('プレビューの表示に失敗:', error);
      }
    }
  });

  // 仕入先データを動的に読み込み
  window.aivicApi.list(1).then(suppliers => {
    if (suppliers && suppliers.length > 0) {
      const checkboxContainer = container.querySelector('#supplier-checkboxes');
      checkboxContainer.innerHTML = suppliers.map(supplier => `
        <label style="display: flex; align-items: center; gap: 8px; padding: 4px 0; font-size: 14px; color: var(--text);">
          <input type="checkbox" value="${supplier.id}" style="accent-color: var(--primary);">
          ${supplier.仕入先名 || supplier.name || '仕入先'}
        </label>
      `).join('');
    }
  }).catch(error => {
    console.error('仕入先データの読み込みに失敗:', error);
  });
}

function(container, apiUrl, tables) {
  // 発注履歴テーブルの再描画
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    tbody.innerHTML = orders.map(order => {
      const statusColor = order.発注ステータス === '入荷済み' ? '#22c55e' : 
                         order.発注ステータス === 'キャンセル' ? '#ef4444' : '#f59e0b';
      return `
        <tr data-id="${order.id}">
          <td style="font-size: 12px; font-weight: 500;">${order.発注番号 || ''}</td>
          <td style="font-size: 12px;">${order.商品名 || ''}</td>
          <td style="font-size: 12px;">${order.仕入先名 || ''}</td>
          <td style="font-size: 12px; text-align: right;">${order.発注数量 || 0}${order.単位 || ''}</td>
          <td style="font-size: 12px;">${order.納期予定日 ? new Date(order.納期予定日).toLocaleDateString('ja-JP') : ''}</td>
          <td><span style="font-size: 11px; padding: 2px 6px; background: ${statusColor}20; color: ${statusColor}; border-radius: 10px;">${order.発注ステータス || ''}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 在庫状況グラフの描画
  function drawStockChart() {
    const canvas = container.querySelector('#stock-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    canvas.width = 280;
    canvas.height = 200;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const data = [
      { label: '正常', value: 45, color: '#22c55e' },
      { label: '不足', value: 8, color: '#f59e0b' },
      { label: '欠品', value: 3, color: '#ef4444' }
    ];

    const total = data.reduce((sum, item) => sum + item.value, 0);
    let currentAngle = -Math.PI / 2;
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2 - 10;
    const radius = 60;

    // 円グラフ描画
    data.forEach(item => {
      const sliceAngle = (item.value / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = item.color;
      ctx.fill();

      currentAngle += sliceAngle;
    });

    // 中央の白い円
    ctx.beginPath();
    ctx.arc(centerX, centerY, 25);
    ctx.fillStyle = '#1a1a1a';
    ctx.fill();

    // 合計数表示
    ctx.fillStyle = '#ffffff';
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(total.toString(), centerX, centerY + 5);
    ctx.font = '10px sans-serif';
    ctx.fillText('商品', centerX, centerY + 18);
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('[data-testid="product-search-input"]').value.trim();
    const resultsDiv = container.querySelector('#search-results');

    if (!keyword) {
      resultsDiv.innerHTML = '商品名または商品コードを入力して検索してください';
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (!products) {
        resultsDiv.innerHTML = 'データの取得に失敗しました';
        return;
      }

      const filtered = products.filter(p => 
        (p.商品名 && p.商品名.includes(keyword)) || 
        (p.商品コード && p.商品コード.includes(keyword))
      );

      if (filtered.length === 0) {
        resultsDiv.innerHTML = '該当する商品が見つかりませんでした';
      } else {
        resultsDiv.innerHTML = filtered.slice(0, 3).map(p => 
          `<div style="padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
            <div style="font-weight: 500;">${p.商品名 || ''}</div>
            <div style="font-size: 11px; color: var(--text-muted);">コード: ${p.商品コード || ''} | 在庫: ${p.現在庫数量 || 0}${p.単位 || ''}</div>
          </div>`
        ).join('') + (filtered.length > 3 ? `<div style="padding: 4px 0; color: var(--text-muted);">他${filtered.length - 3}件</div>` : '');
      }
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(3).then(orders => {
    if (orders) {
      renderOrders(orders.slice(0, 8)); // 最新8件を表示
    }
  });

  // 在庫データから統計を更新
  window.aivicApi.list(4).then(stocks => {
    if (stocks) {
      const normal = stocks.filter(s => s.在庫状況 === '正常').length;
      const low = stocks.filter(s => s.在庫状況 === '不足').length;
      const out = stocks.filter(s => s.在庫状況 === '欠品').length;

      container.querySelector('#normal-stock').textContent = normal;
      container.querySelector('#low-stock').textContent = low;
      container.querySelector('#out-stock').textContent = out;
    }
  });

  // 棚卸データから進捗を更新
  window.aivicApi.list(5).then(inventories => {
    if (inventories) {
      const completed = inventories.filter(i => i.棚卸ステータス === '完了' || i.棚卸ステータス === '承認済み').length;
      const total = inventories.length;
      const progress = total > 0 ? Math.round((completed / total) * 100) : 0;

      container.querySelector('#inventory-progress').textContent = `${progress}%`;
      container.querySelector('#inventory-progress-bar').style.width = `${progress}%`;
      container.querySelector('#inventory-completed').textContent = `${completed}社`;
      container.querySelector('#inventory-pending').textContent = `${total - completed}社`;
    }
  });

  // グラフ描画
  drawStockChart();

  // イベントリスナー
  container.querySelector('[data-testid="product-search-btn"]').addEventListener('click', searchProducts);

  container.querySelector('[data-testid="product-search-input"]').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      searchProducts();
    }
  });

  container.querySelector('[data-testid="order-status-filter"]').addEventListener('change', (e) => {
    const status = e.target.value;
    window.aivicApi.list(3).then(orders => {
      if (orders) {
        const filtered = status ? orders.filter(o => o.発注ステータス === status) : orders;
        renderOrders(filtered.slice(0, 8));
      }
    });
  });

  container.querySelector('[data-testid="refresh-orders"]').addEventListener('click', () => {
    window.aivicApi.list(3).then(orders => {
      if (orders) {
        renderOrders(orders.slice(0, 8));
      }
    });
  });

  // 画面遷移
  container.querySelector('[data-testid="data-extract-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1780996682301');
  });

  container.querySelector('[data-testid="inventory-report-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1780996691927');
  });

  container.querySelector('[data-testid="report-generate-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1780996715569');
  });

  container.querySelector('[data-testid="view-inventory-detail"]').addEventListener('click', () => {
    window.showScreen('scr-1780996691927');
  });

  container.querySelector('[data-testid="extraction-history-link"]').addEventListener('click', (e) => {
    e.preventDefault();
    window.showScreen('scr-1780996682301');
  });
}
